-- rowfence 0.1.0-dev: language_review. Generated by rowfence migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- - role conf_app
-- - rules app.notes: insert : project.edit and {author_id = authz.uid()}
-- + app role conf_app
-- + rules app.notes: insert : project.edit and author

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', 'cd34c270fcd5f794', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'cd34c270fcd5f794' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'cd34c270fcd5f794' THEN
    RAISE EXCEPTION 'rowfence: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute
             WHERE attrelid = to_regclass('authz.policy_versions') AND attname = 'lock' AND NOT attisdropped) THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock IS DISTINCT FROM 'dcc04f023578dd4c' THEN
    RAISE EXCEPTION 'rowfence: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'dcc04f023578dd4c', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowfence push or apply since needs the '
                   'migrations from the start (or rowfence apply of the policy the previous migration left)';
  END IF;
END $authz_guard$;

-- what goes, or is made again
DROP POLICY IF EXISTS "authz_insert" ON "app"."notes";
DROP FUNCTION IF EXISTS
  authz_gen."app.notes:insert:items"(p_row "app"."notes");

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowfence''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

CREATE FUNCTION authz_gen."app.notes:insert:items"(p_row "app"."notes") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce((coalesce("notes"."author_id" = (SELECT authz.uid()), false)
    AND EXISTS (SELECT 1 FROM authz_gen."project__edit" v WHERE v.id = "notes"."project_id")), false),
    coalesce((SELECT authz_int.scope_cmd('app.notes', 'insert')), false),
    coalesce(true, false),
    coalesce(EXISTS (SELECT 1 FROM authz_gen."project__edit" v WHERE v.id = "notes"."project_id"), false),
    coalesce(coalesce("notes"."author_id" = (SELECT authz.uid()), false), false)]
  FROM (SELECT (p_row).*) AS "notes";
END;

CREATE OR REPLACE FUNCTION authz_gen."app.notes:insert:why"(p_row "app"."notes") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.notes:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : project.edit and author  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.notes insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on app.notes'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'project.edit';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("notes"."project_id")::text AS id FROM (SELECT (p_row).*) AS "notes") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('project', v_t.id, 'edit') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || 'author';
END $f$;

-- app.notes insert (line 35): project.edit and author
CREATE POLICY "authz_insert" ON "app"."notes" FOR INSERT TO conf_app
  WITH CHECK (((SELECT authz_int.scope_cmd('app.notes', 'insert')) AND (coalesce("notes"."author_id" = (SELECT authz.uid()), false)
    AND EXISTS (SELECT 1 FROM authz_gen."project__edit" v WHERE v.id = "notes"."project_id")))
    OR authz_gen."app.notes:insert:refuse"(ROW("notes".*)::"app"."notes"));
COMMENT ON POLICY "authz_insert" ON "app"."notes" IS 'authzc';

CREATE OR REPLACE FUNCTION authz_gen."app.inbox:insert:why"(p_row "app"."inbox") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.inbox:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : signed_in and {sender_id = authz.uid()}  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.inbox insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on app.inbox'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'signed_in';
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || '{sender_id = authz.uid()}';
END $f$;

-- Privileges the policy doesn't give on rowfence's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'conf_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'conf_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'conf_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'conf_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'conf_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.roles_of(text, bigint)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.start_review(text, bigint, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowfence''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO conf_app;

GRANT SELECT ON ALL TABLES IN SCHEMA authz_gen TO conf_app;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA authz_gen TO conf_app;

GRANT EXECUTE ON FUNCTION
  authz.uid(),
  authz.principal(),
  authz.ctx(text),
  authz.link_hashes(),
  authz.act_as(text, text),
  authz.connection_check(),
  authz.can(text, text, text),
  authz.list(text, text, text, integer),
  authz.perms(text, text),
  authz.perms_of(text, text[]),
  authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb),
  authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.unshare(text, text, text, text, text, text),
  authz.unshare(text, bigint, text, text, bigint, text),
  authz.unshare(text, bigint, text, text, text, text),
  authz.create_link(text, text, text, timestamptz),
  authz.create_link(text, bigint, text, timestamptz),
  authz.create_role(text, text, text, text, text[]),
  authz.create_role(text, bigint, text, text, text[]),
  authz.set_role_permissions(bigint, text[]),
  authz.delete_role(bigint),
  authz.roles_of(text, text),
  authz.roles_of(text, bigint),
  authz.who(text, text, text),
  authz.explain(text, text, text, text),
  authz.list_shares(text, text),
  authz.explain_rule(text, text, text, jsonb),
  authz.who_among(text, text, text, text[], text),
  authz.create_api_key(text, text, timestamptz, text, text),
  authz.list_api_keys(text, text),
  authz.revoke_api_key(bigint),
  authz.login_key(text),
  authz.login_jwt(text),
  authz.view_as(text, text),
  authz.request_access(text, text, text, text, interval),
  authz.request_access(text, bigint, text, text, interval),
  authz.pending_requests(),
  authz.decide_request(bigint, boolean, text),
  authz.cancel_request(bigint),
  authz.break_glass(text, text, text, text, interval),
  authz.break_glass(text, bigint, text, text, interval),
  authz.start_review(text, text, timestamptz),
  authz.start_review(text, bigint, timestamptz),
  authz.review_items(bigint),
  authz.review_decide(bigint, integer, boolean),
  authz.close_review(bigint, boolean),
  authz.who(text, bigint, text),
  authz.explain(text, bigint, text, text),
  authz.list_shares(text, bigint),
  authz.can(text, bigint, text),
  authz.who_among(text, bigint, text, text[], text),
  authz.perms(text, bigint)
  TO conf_app;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- The conformance app's policy: projects with an owner and members, public ones anyone may read, a service
-- that reads the projects it is added to, notes in projects, and an inbox only its recipient reads.

app role conf_app

type user = app.users

type service = app.services principal

type project = app.projects
  owner   : user    = owner_id
  member  : user    = app.members(project_id -> user_id)
  service : service = app.project_services(project_id -> service_id)

  can edit = owner or member
  can view = edit or service or {public}

type note = app.notes
  project : project = project_id
  author  : user    = author_id

  can edit = author or project.owner
  can view = project.view

type message = app.inbox
  recipient : user = recipient_id

  can read = recipient

rules app.projects
  select : view

rules app.notes
  select : view
  insert : project.edit and author
  update : edit
  delete : edit

rules app.inbox
  select : read
  insert : signed_in and {sender_id = authz.uid()}
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+fa6472acfadf', 'cd34c270fcd5f794');
